/* ---------- tutorial ---------- */
// Cada paso es un par de claves i18n [título, cuerpo HTML]; se resuelven con
// t() al pintar, así el tutorial sale en el idioma activo.
const TUTO={
  carrera:[1,2,3,4,5,6].map(i=>[`tuto_ca_${i}_t`,`tuto_ca_${i}_x`]),
  club:[1,2,3,4,5,6].map(i=>[`tuto_cl_${i}_t`,`tuto_cl_${i}_x`]),
};
let tutoIdx=0, tutoModo="carrera";
function verTuto(modo,force){
  if(!force){ try{ if(localStorage.getItem("rpm_tuto_"+modo)) return; }catch(e){} }
  tutoModo=modo; tutoIdx=0;
  document.getElementById("tuto").classList.remove("oculto");
  pintaTuto();
}
function pintaTuto(){
  const pasos=TUTO[tutoModo], p=pasos[tutoIdx];
  document.getElementById("tutoTit").textContent=t(p[0]);
  document.getElementById("tutoPaso").textContent=t("tuto_paso",{i:tutoIdx+1,n:pasos.length});
  document.getElementById("tutoTxt").innerHTML=t(p[1]);
  document.getElementById("tutoSig").textContent=tutoIdx===pasos.length-1?t("tuto_fin"):t("tuto_sig");
}
function cierraTuto(){
  document.getElementById("tuto").classList.add("oculto");
  try{ localStorage.setItem("rpm_tuto_"+tutoModo,"1"); }catch(e){}
}
document.getElementById("tutoSig").onclick=()=>{
  if(tutoIdx>=TUTO[tutoModo].length-1){ cierraTuto(); return; }
  tutoIdx++; pintaTuto();
};
document.getElementById("tutoSaltar").onclick=cierraTuto;

// Chips de rasgos de un jugador (verde=bueno, rojo=lastre, oro=neutro).
function chipRasgos(j){
  const rg=(typeof rasgosDe==="function")?rasgosDe(j):[];
  if(!rg||!rg.length) return "";
  return rg.map(id=>{ const r=(typeof RASGOS!=="undefined"&&RASGOS[id])||{n:id,bueno:0,desc:""};
    const col=r.bueno>0?"var(--verde)":r.bueno<0?"var(--rojo)":"var(--oro)";
    // n y desc son claves i18n; t() devuelve tal cual lo que no reconoce, así
    // que los guardados antiguos con el literal dentro siguen pintando bien
    return `<span class="rasgo" title="${r.desc?t(r.desc):""}" style="border-color:${col};color:${col}">${t(r.n)}</span>`; }).join("");
}


/* ================= PANEL DE MANDO (escritorio) ================= */
function hudCaja(titulo,filas){ return `<div class="hudCaja"><div class="hudTit">${titulo}</div>${filas}</div>`; }
function hudFila(etq,val,color){ return `<div class="hudFila"><span>${etq}</span><b${color?` style="color:${color}"`:""}>${val}</b></div>`; }
function hudStaff(){
  const e=ent(); if(!e||!e.staff) return "";
  return hudCaja(t("hud_equipo"), rolesDeModo().map(r=>{
    const st=e.staff[r], info=ROLES_STAFF[r];
    return hudFila(`${info.ico} ${t("rol_"+r).split("/")[0]}`, st?"★".repeat(st.niv):"—", st?"":"var(--gris2)");
  }).join(""));
}
function hudEvento(){
  if(torneo) return hudCaja(t("hud_enjuego"), hudFila(faseNombre(torneo.fase), `<span style="font-size:12px">${torneo.nombre}</span>`));
  let f=""; const sl=slotSemana(semanaTemp());
  if(sl){
    if(sl.premier!==undefined) f+=hudFila(t("sem_tag_elite"),`<span style="font-size:12px">${catNombre(sl.premier)}</span>`);
    if(sl.fip!==undefined) f+=hudFila(t("sem_tag_cont"),`<span style="font-size:12px">${catNombre(sl.fip)}</span>`);
  }
  return f?hudCaja(t("hud_estasem"),f):"";
}
function pintarHUD(){
  const hud=document.getElementById("hud");
  if(!hud||!G) return;
  const dinCol=(v)=>v<0?"#E05656":"var(--lima)";
  let html="";
  if(G.modo==="carrera"){
    const c=G.carrera; if(!c) return;
    const tm=miTeam(), js=(tm&&tm.jug)||[];
    html+=`<div class="hudCaja">
      <div style="display:flex;gap:5px;align-items:center;margin-bottom:5px">
        ${js.map(j=>avatarSVG(j,34)).join("")}
        <div style="min-width:0">
          <div class="hudNom">${c.nombre}</div>
          <div style="font-size:10px;color:var(--gris)">${t("hud_con",{n:c.compi?c.compi.n:"—"})}</div>
        </div>
      </div>
      <div>${js.map(j=>ladoChip(j.lado)).join(" ")}</div>
    </div>`;
    html+=hudCaja(t("hud_temporada",{t:temporada()}),
      hudFila(t("hud_semana"),`${semanaTemp()}<span style="font-size:10px;color:var(--gris)">/52</span>`)+
      hudFila(t("hud_puesto"),`#${miPuesto()}`)+
      hudFila(t("hud_puntos"),c.pts)+
      hudFila(t("hud_caja"),`${(c.dinero||0).toLocaleString("es")}€`,dinCol(c.dinero||0))+
      hudFila(t("hud_energia"),Math.round(c.energia||0))+
      (c.fans!==undefined?hudFila(t("hud_seguidores"),fmtFans(c.fans)):""));
  } else {
    const cl=G.clubG; if(!cl) return;
    const al=alineacion()||[];
    html+=`<div class="hudCaja">
      <div style="display:flex;gap:5px;align-items:center;margin-bottom:5px">
        <div style="width:12px;height:34px;border-radius:2px;background:${cl.color||"#C6F53C"}"></div>
        ${al.map(j=>avatarSVG(j,34)).join("")}
        <div style="min-width:0"><div class="hudNom">${cl.nombre}</div>
        <div style="font-size:10px;color:var(--gris)">${t("hud_jugadores",{n:(cl.plantilla||[]).length})}</div></div>
      </div>
      <div>${al.map(j=>ladoChip(j.lado)).join(" ")}</div>
    </div>`;
    html+=hudCaja(t("hud_temporada",{t:temporada()}),
      hudFila(t("hud_semana"),`${semanaTemp()}<span style="font-size:10px;color:var(--gris)">/52</span>`)+
      hudFila(t("hud_puesto"),`#${miPuesto()}`)+
      hudFila(t("hud_puntos"),cl.pts)+
      hudFila(t("hud_caja"),`${(cl.dinero||0).toLocaleString("es")}€`,dinCol(cl.dinero||0))+
      hudFila(t("hud_instal"),"★".repeat(cl.instal||1))+
      (cl.fans!==undefined?hudFila(t("hud_seguidores"),fmtFans(cl.fans)):""));
  }
  html+=hudEvento();
  html+=hudStaff();
  html+=`<div style="font-size:9px;color:var(--gris2);letter-spacing:1px;text-align:center;margin-top:auto;padding-top:8px">${t("hud_atajos")}</div>`;
  hud.innerHTML=html;
}

/* el panel se refresca con cada repintado y solo aparece dentro de una partida */
(function(){
  const _car=pintarCarrera, _clu=pintarClubM, _ir=irA;
  pintarCarrera=function(){ const r=_car.apply(null,arguments); try{ pintarHUD(); }catch(e){} return r; };
  pintarClubM  =function(){ const r=_clu.apply(null,arguments); try{ pintarHUD(); }catch(e){} return r; };
  irA=function(sc){
    const r=_ir.apply(null,arguments);
    try{
      // el panel lateral (y el hueco que le reserva .wrap) se mantiene también en
      // la pantalla de torneo; solo desaparece dentro del partido (pista a pantalla
      // completa). Sin esto, el HUD fijo tapaba la tarjeta del rival en escritorio.
      const dentro=(sc==="club"||sc==="clubm"||sc==="torneo");
      document.body.classList.toggle("con-hud",dentro);
      if(dentro) pintarHUD();
    }catch(e){}
    return r;
  };
})();

/* atajos de teclado */
document.addEventListener("keydown",(e)=>{
  if(e.key==="Escape"){
    ["modoModal","clubModal","anuarioModal"].forEach(id=>{ const m=document.getElementById(id); if(m) quitarEl(m); });
    return;
  }
  if(!G||!G.modo) return;
  const n=parseInt(e.key,10);
  if(!n||n<1||n>6) return;
  const ids = G.modo==="carrera"
    ? ["tabSemana","tabEntreno","tabStaff","tabJugador","tabRanking","tabDiario"]
    : ["cmTabSemana","cmTabPlantilla","cmTabClub","cmTabRanking","cmTabDiario"];
  const b=ids[n-1]&&document.getElementById(ids[n-1]);
  if(b&&b.onclick) b.onclick();
});

/* ---------- logos de marca ---------- */
const LOGO_ESTUDIO="data:image/jpeg;base64,";
const LOGO_JUEGO="data:image/jpeg;base64,";
function pintarLogos(){
  const set=(id,src)=>{ const e=document.getElementById(id); if(e) e.src=src; };
  set("splImgEstudio",LOGO_ESTUDIO);
  set("splImgJuego",LOGO_JUEGO);     set("menuImgJuego",LOGO_JUEGO);
}


